312	// CreateJournal posts an immutable voucher once it balances in the functional
313	// currency.
314	func (s *Service) CreateJournal(body []byte, key string) (any, error) {
315		var request createJournalRequest
316		if err := decodeObject(body, &request); err != nil {
317			return nil, err
318		}
319		id, err := validateIdentifier(request.ID, "journal id")
320		if err != nil {
321			return nil, err
322		}
323		date, err := validateDate(request.Date, "date")
324		if err != nil {
325			return nil, err
326		}
327		memo, err := validateText(request.Memo, "memo")
328		if err != nil {
329			return nil, err
330		}
331		if len(request.Lines) < 2 {
332			return nil, ValidationError("lines must contain at least two postings")
333		}
334		return s.runIdempotent(key, "create-journal:"+id, func(state *State) (any, error) {
335			if _, found := state.Journals[id]; found {
336				return nil, ConflictError("journal %s already exists", id)
337			}
338			journal := &Journal{
339				ID:                 id,
340				Date:               date,
341				Memo:               memo,
342				FunctionalCurrency: s.functionalCurrency,
343				Lines:              []*JournalLine{},
344				CreatedAt:          s.now(),
345			}
346			var debits, credits int64
347			for position, raw := range request.Lines {
348				line, err := s.buildJournalLine(state, raw, position+1, date)
349				if err != nil {
350					return nil, err
351				}
352				if line.Side == "debit" {
353					debits += line.FunctionalAmountMinor
354				} else {
355					credits += line.FunctionalAmountMinor
356				}
357				journal.Lines = append(journal.Lines, line)
358			}
359			if debits != credits {
360				return nil, ValidationError(
361					"journal is not balanced in %s: debits %d, credits %d",
362					s.functionalCurrency, debits, credits,
363				)
364			}
365			journal.DebitFunctionalMinor = debits
366			journal.CreditFunctionalMinor = credits
367			state.Journals[id] = journal
368			return journal, nil
369		})
370	}
