383	func (s *Service) buildJournalLine(state *State, raw *journalLineRequest, index int, date string) (*JournalLine, error) {
384		if raw == nil {
385			return nil, ValidationError("lines[%d] must be an object", index)
386		}
387		accountID, err := validateIdentifier(raw.AccountID, fmt.Sprintf("lines[%d].account_id", index))
388		if err != nil {
389			return nil, err
390		}
391		account, found := state.Accounts[accountID]
392		if !found {
393			return nil, ValidationError("lines[%d].account_id %s does not exist", index, accountID)
394		}
395		if raw.Side != "debit" && raw.Side != "credit" {
396			return nil, ValidationError("lines[%d].side must be debit or credit", index)
397		}
398		amount, err := validateAmount(raw.AmountMinor, fmt.Sprintf("lines[%d].amount_minor", index), false, false)
399		if err != nil {
400			return nil, err
401		}
402		currency, err := validateCurrency(raw.Currency, fmt.Sprintf("lines[%d].currency", index), false)
403		if err != nil {
404			return nil, err
405		}
406		if currency == "" {
407			currency = account.Currency
408		}
409		if currency != account.Currency {
410			return nil, ValidationError(
411				"lines[%d].currency %s must match the currency %s of account %s",
412				index, currency, account.Currency, accountID,
413			)
414		}
415		reference, err := validateText(raw.Reference, fmt.Sprintf("lines[%d].reference", index))
416		if err != nil {
417			return nil, err
418		}
419		numerator, denominator, source, err := s.resolveRate(state, currency, date, raw.Rate, fmt.Sprintf("lines[%d].rate", index))
420		if err != nil {
421			return nil, err
422		}
423		functional, err := convertMinor(amount, numerator, denominator)
424		if err != nil {
425			return nil, err
426		}
427		if functional < 1 {
428			return nil, ValidationError(
429				"lines[%d] converts to zero minor units in %s; use a larger amount or a finer exchange rate",
430				index, s.functionalCurrency,
431			)
432		}
433		return &JournalLine{
434			Index:                 index,
435			AccountID:             accountID,
436			Side:                  raw.Side,
437			AmountMinor:           amount,
438			Currency:              currency,
439			Rate:                  raw.Rate,
440			RateNumerator:         numerator,
441			RateDenominator:       denominator,
442			RateSource:            source,
443			FunctionalAmountMinor: functional,
444			Reference:             reference,
445		}, nil
446	}
