448	// resolveRate returns the exact fraction that converts one minor unit of
449	// currency into the functional currency for the given date.
450	func (s *Service) resolveRate(state *State, currency, date, declared, field string) (int64, int64, string, error) {
451		if currency == s.functionalCurrency {
452			if declared == "" || declared == "1" {
453				return 1, 1, "identity", nil
454			}
455			numerator, denominator, err := parseRateFraction(declared, field)
456			if err != nil {
457				return 0, 0, "", err
458			}
459			if numerator != denominator {
460				return 0, 0, "", ValidationError(
461					"%s must be omitted or exactly 1 because %s is the functional currency",
462					field, currency,
463				)
464			}
465			return 1, 1, "identity", nil
466		}
467		if declared != "" {
468			numerator, denominator, err := parseRateFraction(declared, field)
469			if err != nil {
470				return 0, 0, "", err
471			}
472			return numerator, denominator, "declared", nil
473		}
474		if direct := latestRate(state, currency, s.functionalCurrency, date); direct != nil {
475			return direct.Numerator, direct.Denominator, "snapshot:" + direct.Date, nil
476		}
477		if inverse := latestRate(state, s.functionalCurrency, currency, date); inverse != nil {
478			return inverse.Denominator, inverse.Numerator, "snapshot-inverse:" + inverse.Date, nil
479		}
480		return 0, 0, "", ValidationError(
481			"no %s/%s exchange rate snapshot exists on or before %s",
482			currency, s.functionalCurrency, date,
483		)
484	}
