509	// CreateStatement imports one bank statement.
510	func (s *Service) CreateStatement(body []byte, key string) (any, error) {
511		var request createStatementRequest
512		if err := decodeObject(body, &request); err != nil {
513			return nil, err
514		}
515		id, err := validateIdentifier(request.ID, "statement id")
516		if err != nil {
517			return nil, err
518		}
519		accountID, err := validateIdentifier(request.AccountID, "account_id")
520		if err != nil {
521			return nil, err
522		}
523		currency, err := validateCurrency(request.Currency, "currency", false)
524		if err != nil {
525			return nil, err
526		}
527		start, err := validateDate(request.Period.Start, "period.start")
528		if err != nil {
529			return nil, err
530		}
531		end, err := validateDate(request.Period.End, "period.end")
532		if err != nil {
533			return nil, err
534		}
535		if start > end {
536			return nil, ValidationError("period.start must not be after period.end")
537		}
538		opening, err := validateAmount(request.OpeningBalanceMinor, "opening_balance_minor", true, true)
539		if err != nil {
540			return nil, err
541		}
542		closing, err := validateAmount(request.ClosingBalanceMinor, "closing_balance_minor", true, true)
543		if err != nil {
544			return nil, err
545		}
546		return s.runIdempotent(key, "create-statement:"+id, func(state *State) (any, error) {
547			if _, found := state.Statements[id]; found {
548				return nil, ConflictError("statement %s already exists", id)
549			}
550			account, found := state.Accounts[accountID]
551			if !found {
552				return nil, ValidationError("account_id %s does not exist", accountID)
553			}
554			if currency == "" {
555				currency = account.Currency
556			}
557			if currency != account.Currency {
558				return nil, ValidationError(
559					"currency %s must match the currency %s of account %s",
560					currency, account.Currency, accountID,
561				)
562			}
563			statement := &Statement{
564				ID:                  id,
565				AccountID:           accountID,
566				Currency:            currency,
567				Period:              Period{Start: start, End: end},
568				OpeningBalanceMinor: opening,
569				ClosingBalanceMinor: closing,
570				Lines:               []*StatementLine{},
571				CreatedAt:           s.now(),
572			}
573			total := opening
574			seen := map[string]bool{}
575			for position, raw := range request.Lines {
576				if raw == nil {
577					return nil, ValidationError("lines[%d] must be an object", position+1)
578				}
579				field := fmt.Sprintf("lines[%d]", position+1)
580				lineID, err := validateIdentifier(raw.ID, field+".id")
581				if err != nil {
582					return nil, err
583				}
584				if seen[lineID] {
585					return nil, ValidationError("statement line id %s is duplicated", lineID)
586				}
587				seen[lineID] = true
588				lineDate, err := validateDate(raw.Date, field+".date")
589				if err != nil {
590					return nil, err
591				}
592				if lineDate < start || lineDate > end {
593					return nil, ValidationError("%s.date must fall inside the statement period", field)
594				}
595				amount, err := validateAmount(raw.AmountMinor, field+".amount_minor", false, true)
596				if err != nil {
597					return nil, err
598				}
599				reference, err := validateText(raw.Reference, field+".reference")
600				if err != nil {
601					return nil, err
602				}
603				description, err := validateText(raw.Description, field+".description")
604				if err != nil {
605					return nil, err
606				}
607				total += amount
608				statement.Lines = append(statement.Lines, &StatementLine{
609					ID:          lineID,
610					Date:        lineDate,
611					AmountMinor: amount,
612					Reference:   reference,
613					Description: description,
614				})
615			}
616			if total != closing {
617				return nil, ValidationError(
618					"statement lines do not reconcile with the closing balance: opening %d plus lines %d is %d, not %d",
619					opening, total-opening, total, closing,
620				)
621			}
622			state.Statements[id] = statement
623			return statement, nil
624		})
625	}
