686	// ledgerEntry is one journal line seen from the ledger side of a
687	// reconciliation. AmountMinor is signed with debits positive.
688	type ledgerEntry struct {
689		ID          string
690		Date        string
691		AmountMinor int64
692		Reference   string
693	}
694	
695	func ledgerEntries(state *State, accountID string, period Period) []*ledgerEntry {
696		entries := []*ledgerEntry{}
697		for _, journal := range sortedJournals(state) {
698			if journal.Date < period.Start || journal.Date > period.End {
699				continue
700			}
701			for _, line := range journal.Lines {
702				if line.AccountID != accountID {
703					continue
704				}
705				amount := line.AmountMinor
706				if line.Side == "credit" {
707					amount = -amount
708				}
709				entries = append(entries, &ledgerEntry{
710					ID:          fmt.Sprintf("%s#%d", journal.ID, line.Index),
711					Date:        journal.Date,
712					AmountMinor: amount,
713					Reference:   line.Reference,
714				})
715			}
716		}
717		return entries
718	}
719	
720	var differenceOrder = map[string]int{
721		"timing":               0,
722		"amount_mismatch":      1,
723		"missing_in_ledger":    2,
724		"missing_in_statement": 3,
725	}
726	
727	// computeReconciliation matches statement lines to ledger lines in three
728	// deterministic tiers and classifies everything that stays unmatched.
729	func (s *Service) computeReconciliation(state *State, statement *Statement, id, createdAt string) (*Reconciliation, error) {
730		lines := make([]*StatementLine, 0, len(statement.Lines))
731		lines = append(lines, statement.Lines...)
732		sort.Slice(lines, func(left, right int) bool { return lines[left].ID < lines[right].ID })
733	
734		entries := ledgerEntries(state, statement.AccountID, statement.Period)
735		sort.Slice(entries, func(left, right int) bool { return entries[left].ID < entries[right].ID })
736	
737		statementUsed := make([]bool, len(lines))
738		ledgerUsed := make([]bool, len(entries))
739		differences := []*Difference{}
740		matched := 0
741		match := func(statementIndex, ledgerIndex int, difference *Difference) {
742			statementUsed[statementIndex] = true
743			ledgerUsed[ledgerIndex] = true
744			matched++
745			if difference != nil {
746				differences = append(differences, difference)
747			}
748		}
749	
750		// Tier 1: same signed amount and same date.
751		for index, line := range lines {
752			for other, entry := range entries {
753				if ledgerUsed[other] {
754					continue
755				}
756				if entry.AmountMinor == line.AmountMinor && entry.Date == line.Date {
757					match(index, other, nil)
758					break
759				}
760			}
761		}
762	
763		// Tier 2: same signed amount, different date, so it only differs in timing.
764		for index, line := range lines {
765			if statementUsed[index] {
766				continue
767			}
768			for other, entry := range entries {
769				if ledgerUsed[other] || entry.AmountMinor != line.AmountMinor {
770					continue
771				}
772				statementAmount := line.AmountMinor
773				ledgerAmount := entry.AmountMinor
774				match(index, other, &Difference{
775					Type:                 "timing",
776					Detail:               "the amounts agree but the ledger date differs from the statement date",
777					StatementLineID:      line.ID,
778					LedgerLineID:         entry.ID,
779					StatementDate:        line.Date,
780					LedgerDate:           entry.Date,
781					StatementAmountMinor: &statementAmount,
782					LedgerAmountMinor:    &ledgerAmount,
783				})
784				break
785			}
786		}
787	
788		// Tier 3: same non-empty reference but a different amount.
789		for index, line := range lines {
790			if statementUsed[index] || line.Reference == "" {
791				continue
792			}
793			for other, entry := range entries {
794				if ledgerUsed[other] || entry.Reference == "" || entry.Reference != line.Reference {
795					continue
796				}
797				statementAmount := line.AmountMinor
798				ledgerAmount := entry.AmountMinor
799				match(index, other, &Difference{
800					Type:                 "amount_mismatch",
801					Detail:               fmt.Sprintf("reference %s appears on both sides with different amounts", line.Reference),
802					StatementLineID:      line.ID,
803					LedgerLineID:         entry.ID,
804					StatementDate:        line.Date,
805					LedgerDate:           entry.Date,
806					StatementAmountMinor: &statementAmount,
807					LedgerAmountMinor:    &ledgerAmount,
808					DifferenceMinor:      statementAmount - ledgerAmount,
809				})
810				break
811			}
812		}
813	
814		// Everything still unmatched is missing on one side.
815		for index, line := range lines {
816			if statementUsed[index] {
817				continue
818			}
819			amount := line.AmountMinor
820			differences = append(differences, &Difference{
821				Type:                 "missing_in_ledger",
822				Detail:               "the statement line has no journal line in the period",
823				StatementLineID:      line.ID,
824				StatementDate:        line.Date,
825				StatementAmountMinor: &amount,
826				DifferenceMinor:      amount,
827			})
828		}
829		for index, entry := range entries {
830			if ledgerUsed[index] {
831				continue
832			}
833			amount := entry.AmountMinor
834			differences = append(differences, &Difference{
835				Type:              "missing_in_statement",
836				Detail:            "the journal line has no statement line in the period",
837				LedgerLineID:      entry.ID,
838				LedgerDate:        entry.Date,
839				LedgerAmountMinor: &amount,
840				DifferenceMinor:   -amount,
841			})
842		}
843	
844		sort.SliceStable(differences, func(left, right int) bool {
845			a, b := differences[left], differences[right]
846			if differenceOrder[a.Type] != differenceOrder[b.Type] {
847				return differenceOrder[a.Type] < differenceOrder[b.Type]
848			}
849			if a.StatementLineID != b.StatementLineID {
850				return a.StatementLineID < b.StatementLineID
851			}
852			return a.LedgerLineID < b.LedgerLineID
853		})
854	
855		var ledgerNet int64
856		for _, entry := range entries {
857			ledgerNet += entry.AmountMinor
858		}
859		statementNet := statement.ClosingBalanceMinor - statement.OpeningBalanceMinor
860	
861		summary := DifferenceSummary{}
862		var explained int64
863		for _, difference := range differences {
864			explained += difference.DifferenceMinor
865			switch difference.Type {
866			case "timing":
867				summary.Timing++
868			case "amount_mismatch":
869				summary.AmountMismatch++
870			case "missing_in_ledger":
871				summary.MissingInLedger++
872			case "missing_in_statement":
873				summary.MissingInStatement++
874			default:
875				return nil, InternalError("reconciliation produced the unknown difference type %s", difference.Type)
876			}
877		}
878		if 2*matched+summary.MissingInLedger+summary.MissingInStatement != len(lines)+len(entries) {
879			return nil, InternalError("reconciliation differences are not mutually exclusive and complete")
880		}
881		if explained != statementNet-ledgerNet {
882			return nil, InternalError("reconciliation differences do not add up to the period difference")
883		}
884	
885		status := "balanced"
886		if len(differences) > 0 {
887			status = "differences_found"
888		}
889		return &Reconciliation{
890			ID:                 id,
891			StatementID:        statement.ID,
892			AccountID:          statement.AccountID,
893			Currency:           statement.Currency,
894			FunctionalCurrency: s.functionalCurrency,
895			Period:             statement.Period,
896			Status:             status,
897			MatchedCount:       matched,
898			StatementLineCount: len(lines),
899			LedgerLineCount:    len(entries),
900			StatementNetMinor:  statementNet,
901			LedgerNetMinor:     ledgerNet,
902			DifferenceMinor:    statementNet - ledgerNet,
903			Summary:            summary,
904			Differences:        differences,
905			CreatedAt:          createdAt,
906		}, nil
907	}
908	
909	func sortedAccounts(state *State) []*Account {
910		accounts := make([]*Account, 0, len(state.Accounts))
911		for _, account := range state.Accounts {
912			accounts = append(accounts, account)
913		}
914		sort.Slice(accounts, func(left, right int) bool { return accounts[left].ID < accounts[right].ID })
915		return accounts
916	}
917	
918	func sortedJournals(state *State) []*Journal {
919		journals := make([]*Journal, 0, len(state.Journals))
920		for _, journal := range state.Journals {
921			journals = append(journals, journal)
922		}
923		sort.Slice(journals, func(left, right int) bool {
924			if journals[left].Date != journals[right].Date {
925				return journals[left].Date < journals[right].Date
926			}
927			return journals[left].ID < journals[right].ID
928		})
929		return journals
930	}
931	
932	func sortedRates(state *State) []*Rate {
933		rates := make([]*Rate, 0, len(state.Rates))
934		rates = append(rates, state.Rates...)
935		sort.Slice(rates, func(left, right int) bool {
936			a, b := rates[left], rates[right]
937			if a.Base != b.Base {
938				return a.Base < b.Base
939			}
940			if a.Quote != b.Quote {
941				return a.Quote < b.Quote
942			}
943			return a.Date < b.Date
944		})
945		return rates
946	}
947	
948	func accountTree(state *State) (map[string]*AccountNode, []*AccountNode) {
949		nodes := map[string]*AccountNode{}
950		for _, account := range state.Accounts {
951			nodes[account.ID] = &AccountNode{Account: *account, Children: []*AccountNode{}}
952		}
953		roots := []*AccountNode{}
954		for _, account := range sortedAccounts(state) {
955			node := nodes[account.ID]
956			if account.ParentID == nil {
957				roots = append(roots, node)
958				continue
959			}
960			parent, found := nodes[*account.ParentID]
961			if !found {
962				roots = append(roots, node)
963				continue
964			}
965			parent.Children = append(parent.Children, node)
966		}
967		return nodes, roots
968	}
969	
970	// latestRate returns the most recent snapshot for one direction that is
971	// effective on the given date.
972	func latestRate(state *State, base, quote, asOf string) *Rate {
973		var best *Rate
974		for _, rate := range state.Rates {
975			if rate.Base != base || rate.Quote != quote || rate.Date > asOf {
976				continue
977			}
978			if best == nil || rate.Date > best.Date {
979				best = rate
980			}
981		}
982		return best
983	}
984

