17		// maxAmountMinor bounds every monetary value so that conversions stay
18		// exactly representable in int64 arithmetic.
19		maxAmountMinor = int64(1_000_000_000_000_000)
20	
21		maxIdentifierLength = 128
22		maxTextLength       = 256
23		maxRateDigits       = 18
24		maxRateDecimals     = 9
25	)
