28	var normalBalanceByType = map[string]string{
29		"asset":     "debit",
30		"expense":   "debit",
31		"liability": "credit",
32		"equity":    "credit",
33		"revenue":   "credit",
34	}
35	
36	// Rate is an immutable exchange rate snapshot: one unit of Base is worth Rate
37	// units of Quote from Date onwards. The decimal string is stored together with
38	// its exact reduced fraction so nothing is ever recomputed from a float.
39	type Rate struct {
40		Base        string `json:"base"`
41		Quote       string `json:"quote"`
42		Date        string `json:"date"`
43		Rate        string `json:"rate"`
44		Numerator   int64  `json:"numerator"`
45		Denominator int64  `json:"denominator"`
46		CreatedAt   string `json:"created_at"`
47	}
48	
49	// IdempotencyRecord stores the first response produced for a key.
