314	// parseRateFraction converts an exact decimal string into a positive reduced
315	// fraction. Exponent notation, signs and more than nine decimals are rejected.
316	func parseRateFraction(value, field string) (int64, int64, error) {
317		invalid := ValidationError("%s must be a positive decimal number such as 7.2450", field)
318		if value == "" {
319			return 0, 0, ValidationError("%s is required", field)
320		}
321		whole, fraction, _ := strings.Cut(value, ".")
322		if strings.Contains(fraction, ".") {
323			return 0, 0, invalid
324		}
325		digits := whole + fraction
326		if digits == "" {
327			return 0, 0, invalid
328		}
329		for index := 0; index < len(digits); index++ {
330			if digits[index] < '0' || digits[index] > '9' {
331				return 0, 0, invalid
332			}
333		}
334		if len(fraction) > maxRateDecimals {
335			return 0, 0, ValidationError("%s must have at most %d decimal places", field, maxRateDecimals)
336		}
337		if len(digits) > maxRateDigits {
338			return 0, 0, ValidationError("%s must have at most %d digits", field, maxRateDigits)
339		}
340		numerator, err := strconv.ParseInt(digits, 10, 64)
341		if err != nil {
342			return 0, 0, invalid
343		}
344		if numerator <= 0 {
345			return 0, 0, ValidationError("%s must be greater than zero", field)
346		}
347		denominator := pow10(len(fraction))
348		divisor := greatestCommonDivisor(numerator, denominator)
349		return numerator / divisor, denominator / divisor, nil
350	}
351	
352	// convertMinor multiplies a minor amount by an exact fraction and rounds half
353	// away from zero, which is the only rounding rule ReconCore uses.
354	func convertMinor(amount, numerator, denominator int64) (int64, error) {
355		if denominator <= 0 || numerator <= 0 {
356			return 0, InternalError("exchange rate fraction is invalid")
357		}
358		product := new(big.Int).Mul(big.NewInt(amount), big.NewInt(numerator))
359		divisor := big.NewInt(denominator)
360		quotient := new(big.Int)
361		remainder := new(big.Int)
362		quotient.QuoRem(product, divisor, remainder)
363		doubled := new(big.Int).Abs(remainder)
364		doubled.Lsh(doubled, 1)
365		if doubled.Cmp(divisor) >= 0 {
366			if quotient.Sign() < 0 {
367				quotient.Sub(quotient, big.NewInt(1))
368			} else {
369				quotient.Add(quotient, big.NewInt(1))
370			}
371		}
372		if !quotient.IsInt64() {
373			return 0, ValidationError("converted amount is outside the supported range")
374		}
375		return quotient.Int64(), nil
376	}
377	
378	func pow10(exponent int) int64 {
379		value := int64(1)
380		for index := 0; index < exponent; index++ {
381			value *= 10
382		}
383		return value
384	}
385	
386	func greatestCommonDivisor(left, right int64) int64 {
387		for right != 0 {
388			left, right = right, left%right
389		}
390		return left
391	}
