57	func (c *client) send(r request) (int, string, map[string]any) {
58		c.t.Helper()
59		var body io.Reader
60		if r.body != "" {
61			body = bytes.NewBufferString(r.body)
62		}
63		httpRequest, err := http.NewRequest(r.method, c.server.URL+r.path, body)
64		if err != nil {
65			c.t.Fatalf("build request: %v", err)
66		}
67		if !r.omitType {
68			contentType := r.contentType
69			if contentType == "" {
70				contentType = "application/json"
71			}
72			httpRequest.Header.Set("Content-Type", contentType)
73		}
74		if r.key != "" {
75			httpRequest.Header.Set("Idempotency-Key", r.key)
76		}
77		response, err := c.server.Client().Do(httpRequest)
78		if err != nil {
79			c.t.Fatalf("%s %s: %v", r.method, r.path, err)
80		}
81		defer response.Body.Close()
82		raw, err := io.ReadAll(response.Body)
83		if err != nil {
84			c.t.Fatalf("read %s %s: %v", r.method, r.path, err)
85		}
86		decoded := map[string]any{}
87		if len(raw) > 0 {
88			if err := json.Unmarshal(raw, &decoded); err != nil {
89				c.t.Fatalf("%s %s returned non-object JSON %s", r.method, r.path, raw)
90			}
91		}
92		return response.StatusCode, string(raw), decoded
93	}
